import network
import time
import urequests

wlan = network.WLAN(network.STA_IF)

def tariro_wifi_connect(ssid, password):
    # Join a Wi-Fi network, giving up after 15 s so the rest of the program still runs.
    wlan.active(True)
    if not wlan.isconnected():
        wlan.connect(ssid, password)
        start = time.ticks_ms()
        while not wlan.isconnected() and time.ticks_diff(time.ticks_ms(), start) < 15000:
            time.sleep_ms(250)
    print("Wi-Fi connected: " + wlan.ifconfig()[0] if wlan.isconnected() else "Wi-Fi not connected")
    return wlan.isconnected()


def tariro_http_get(url):
    # HTTP GET; returns the body, or an empty text if the request fails.
    try:
        response = urequests.get(url)
        body = response.text if response.status_code == 200 else ""
        response.close()
        return body
    except Exception:
        return ""

tariro_wifi_connect("SchoolWiFi", "password")

while True:
    if wlan.isconnected():
        print("My IP: " + wlan.ifconfig()[0])
        print(tariro_http_get("http://example.com/"))
    else:
        print("Not connected to Wi-Fi")
    time.sleep(10)
